CREATE TABLE IF NOT EXISTS user_config (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id VARCHAR(255), app_user_id BIGINT, key_name VARCHAR(255), config_value VARCHAR(255), enabled BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS admin_user (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, roles VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS access_token (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token VARCHAR(2048) NOT NULL, expiry TIMESTAMP WITH TIME ZONE NOT NULL, broker_name VARCHAR(255), user_id BIGINT, broker_credentials_id BIGINT);
CREATE INDEX IF NOT EXISTS idx_user_config_app_user ON user_config(app_user_id);
CREATE INDEX IF NOT EXISTS idx_access_token_broker ON access_token(broker_name,broker_credentials_id);
